       $remove_border = $_SESSION['sc_session'][$this->Ini->sc_page]['cons_distr_custo_geracao_saldo']['css_body_embutida'];
   }
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['cons_distr_custo_geracao_saldo']['proc_pdf'] || $_SESSION['sc_session'][$this->Ini->sc_page]['cons_distr_custo_geracao_saldo']['proc_pdf_vert'])
   {
   }
   else
   {
       $nm_saida->saida("     <TR>\r\n");
       $nm_saida->saida("       <TD>\r\n");
       $nm_saida->saida("       <div class=\"scGridBorder\" style=\"" . (isset($remove_border) ? $remove_border : '') . "\">\r\n");
       if (!$_SESSION['sc_session'][$this->Ini->sc_page]['cons_distr_custo_geracao_saldo']['doc_word'])
