    function scGetColumnOrderRule($fieldName)
    {
        $sortRule = 'nosort';
        if ($_SESSION['sc_session'][$this->Ini->sc_page]['cons_distr_custo_geracao_saldo']['ordem_cmp'] == $fieldName) {
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['cons_distr_custo_geracao_saldo']['ordem_label'] == 'desc') {
                $sortRule = 'desc';
            } else {
                $sortRule = 'asc';
            }
        }
        return $sortRule;
    }

    function scGetColumnOrderIcon($fieldName, $sortRule, $skipUnusedClass = false)
    {
        $unusedClass = $skipUnusedClass ? '' : ' sc-grid-order-icon-unused';        if ('desc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_desc . "\" />";
        } elseif ('asc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_asc . "\" />";
        } elseif ('' != $this->Ini->Label_sort) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort . "\" />";
        } else {
            return '';
        }
    }

    function scIsFieldNumeric($fieldName)
    {
        switch ($fieldName) {
            case "id":
                return true;
            case "valor":
                return true;
            case "container":
                return true;
            case "sit_acomp_container":
                return true;
            case "situacao_container":
                return true;
            case "cod_emit_forn":
                return true;
            case "fornec_pi":
                return true;
            case "id_origem":
                return true;
            case "tipo_movto":
                return true;
        }
        return false;
    }

    function scGetDefaultFieldOrder($fieldName)
    {
        switch ($fieldName) {
            case "id":
                return 'desc';
            case "data":
                return 'desc';
            case "valor":
                return 'desc';
            case "container":
                return 'desc';
            case "sit_acomp_container":
                return 'desc';
            case "situacao_container":
                return 'desc';
            case "dt_prev_chegada":
                return 'desc';
            case "dt_recebto":
                return 'desc';
            case "cod_emit_forn":
                return 'desc';
            case "fornec_pi":
                return 'desc';
            case "dt_registro_pedido":
                return 'desc';
            case "id_origem":
                return 'desc';
            case "tipo_movto":
                return 'desc';
        }
        return 'asc';
    }

